配置窗口全屏模式  在 EntryAbility 中，通过 setWindowLayoutFullScreen()方法将窗口设置为全屏布局，隐藏系统状态栏和导航栏，为应用内容提供完整的屏幕空间。
  // EntryAbility.ets
import { AbilityConstant, UIAbility, Want } from '@kit.AbilityKit';
import { window } from '@kit.ArkUI';
import { BusinessError } from '@kit.BasicServicesKit';

export default class EntryAbility extends UIAbility {
    private windowStage: window.WindowStage | null = null;

    onWindowStageCreate(windowStage: window.WindowStage): void {
        this.windowStage = windowStage;
        windowStage.loadContent('pages/Index', (err) => {
            if (err.code) {
                console.error('Failed to load content:', JSON.stringify(err));
                return;
            }
            console.info('Succeeded in loading content.');
            this.setFullScreen(windowStage);
        });
    }

    private async setFullScreen(windowStage: window.WindowStage): Promise<void> {
        try {
            const mainWindow = await windowStage.getMainWindow();
            await mainWindow.setWindowLayoutFullScreen(true);
            console.info('Succeeded in setting window full screen.');
        } catch (error) {
            console.error('Failed to set window full screen, error code: ' + (error as BusinessError).code);
        }
    }
}

