  let a1 = new ArrayBuffer(10);
// ... a1 被赋值 ...

let a2 = new collections.Uint8Array(5);

// 正确方法：创建ArrayBuffer的视图，然后使用set方法
let view = new Uint8Array(a1);
a2.set(view.subarray(0, 5));

