import { image } from '@kit.ImageKit'
import { resourceManager } from '@kit.LocalizationKit'
import { common } from '@kit.AbilityKit'

@Entry
@ComponentV2
struct Demo {
        @Local crop?: PixelMap
        @Local res: Resource = $r("app.media.simple_img2");

        build() {
			Column() {
				Image(this.res).size({ width: 200, height: 200 }).objectFit(ImageFit.TOP_START)
					.border({ width: 1 })
				Blank().height(20)
				Image(this.crop).size({ width: 200, height: 200 }).objectFit(ImageFit.TOP_START)
					.border({ width: 1 })

				Button("crop").onClick(() => {
					const buffer = this.getFileBuffer(this.res);
					const imageSource: image.ImageSource = image.createImageSource(buffer);
					const imgInfo = imageSource.getImageInfoSync(0);
					//裁剪区域,单位像素
					let region: image.Region = {
							x: 0,
							y: 0,
							size: {
									width: 50,
									height: 50
							}
					};
					let pixelMap = imageSource.createPixelMapSync({
							index: 0,
							desiredSize: imgInfo.size
					});
					pixelMap.cropSync(region);
					this.crop = pixelMap;
				})
			}
			.width('100%')
			.height('100%')
			.justifyContent(FlexAlign.Center)
			.backgroundColor(Color.Grey)
        }

	getFileBuffer(res: Resource): ArrayBuffer | undefined {
		try {
			const context: Context = this.getUIContext().getHostContext() as common.UIAbilityContext;
			const resourceMgr: resourceManager.ResourceManager = context.resourceManager;
