struct GoodThemeDemo {

  @State mode: string = 'light'

  build() {

    Column() {

      Button('切换深色')

        .onClick(() => {

          this.mode = this.mode === 'dark' ? 'light' : 'dark'

        })

      Text('背景正确切换')

        .fontSize(20)

    }

    .width('100%')

    .height('100%')

    .backgroundColor(

      this.mode === 'dark' ? '#1E1E1E' : '#FFFFFF'

    )

  }

}

