在鸿蒙系统（HarmonyOS）环境下，针对 HdsNavigation 自定义组件内部实现页面跳转 的需求，需结合 ArkUI 框架 和 ArkTS 语言 的特性进行实现。以下是鸿蒙原生开发的完整解决方案：
   🌐 鸿蒙系统核心机制  鸿蒙的页面跳转依赖 router 模块（@ohos.router），但自定义组件（@Component）无法直接访问路由对象，因为：
    鸿蒙的路由对象需在 AbilityStage 或 页面级组件 中初始化
  自定义组件是纯 UI 逻辑单元，无生命周期钩子（如 onPageShow）
  直接在组件内调用 router.pushUrl() 会报错：Router instance is not initialized
    ✅ 鸿蒙官方推荐方案（3种实现方式）  方案 1：通过 @Prop 传递路由方法（最安全推荐）  原理：父页面获取路由实例，将跳转函数通过 @Prop 传入子组件
  代码示例：
  // 父页面组件 (MainPage.ets)
import router from '@ohos.router';

@Component
export struct MainPage {
  // 定义路由跳转方法
  private navigateTo = (url: string) => {
    router.pushUrl({ url: url });
  }

  build() {
    Column() {
      // 将跳转函数通过 @Prop 传入 HdsNavigation
      HdsNavigation({ navigate: this.navigateTo })
    }
  }
}

// 自定义组件 (HdsNavigation.ets)
@Component
export struct HdsNavigation {
  // 接收父组件传入的跳转函数
  @Prop navigate: (url: string) => void;

  build() {
    Button('跳转到详情页')
      .onClick(() => {
        // 直接调用传入的函数
        this.navigate('pages/DetailPage');
      })
  }
}
  方案 2：使用 AppStorage 全局状态共享（适合多层嵌套）  原理：将路由实例存入全局状态，子组件直接读取
  代码示例：
  // 在 Application.ets 中初始化
import router from '@ohos.router';

@StorageProp('routerInstance')
class RouterStore {
  static router = router; // 将路由实例存入全局
}

// 父页面（无需额外操作）
@Component
export struct MainPage {
  build() {
    Column() {
      HdsNavigation()
    }
  }
}

// 自定义组件 (HdsNavigation.ets)
@Component
export struct HdsNavigation {
  // 从全局状态获取 router
  @StorageProp('routerInstance') router: any;

  build() {
    Button('跳转到详情页')
      .onClick(() => {
        this.router.pushUrl({ url: 'pages/DetailPage' });
      })
  }
}
