@Component
export struct HdsNavigation {
  // 定义事件
  @Link navigationEvent: CustomEvent<NavigationEvent> = new CustomEvent('navigate');

  build() {
    Button('跳转到详情页')
      .onClick(() => {
        // 触发导航事件
        this.navigationEvent.emit({ url: 'pages/DetailPage' });
      })

尊敬的开发您好，关于你的问题做出一下实现步骤
  以下是具体的实现步骤：
  1. 理解HdsNavigation与NavPathStack的关系
  HdsNavigation组件需要一个NavPathStack实例作为其构造函数的参数，这个实例就是管理整个导航状态的关键对象。因此，要在子组件中进行页面跳转，就必须获取到这个NavPathStack实例的引用1。
  2. 使用Provide/Inject进行跨组件通信
  最推荐的方法是使用ArkTS的Provide/Inject机制，将NavPathStack实例从父组件（即包含HdsNavigation的页面）传递到深层的自定义组件中。
  实现步骤如下：
  - 在父页面中提供 (Provide) NavPathStack
  在包含HdsNavigation的页面（例如Index.ets）中，创建一个NavPathStack实例，并通过@Provide装饰器使其在整个应用的组件树中可用1。
      // Index.ets
      import { HdsNavigation } from '@kit.UIDesignKit';
      import { NavPathStack } from '@kit.ArkUI';
      @Entry
      @Component
      struct Index {
          // 创建并提供NavPathStack实例
          @Provide('pageInfos') pageInfos: NavPathStack = new NavPathStack();
          build() {
              Column() {
                  // 将提供的pageInfos实例传递给HdsNavigation
                  HdsNavigation(this.pageInfos) {
                      // ...
                  }
              }
          }
      }
  - 在自定义组件中注入 (Inject) NavPathStack
  在您抽象出的独立自定义组件中，使用@Inject装饰器来获取父页面提供的NavPathStack实例1。
      // YourCustomComponent.ets
      import { NavPathStack } from '@kit.ArkUI';
      @Component
      export struct YourCustomComponent {
          // 注入从父组件提供的NavPathStack实例
          @Inject('pageInfos') private pageInfos: NavPathStack;
          build() {
              Column() {
                  Button('跳转到新页面')
                      .onClick(() => {
